using System;
using EmberBastion;
class SurrenderChecks {static int n;static void Check(bool v,string m){n++;if(!v)throw new Exception(m);}static void Main(){for(int field=0;field<3;field++){var b=new Battle(5,field);Check(!b.Surrender(),"cannot surrender preparation");Check(b.Place(0,0)&&b.Start(),"start");var checkpoint=b.CopyCombat();for(int i=0;i<180;i++)b.Step(1.0/60);int gold=b.Gold,kills=b.Kills;Check(b.Surrender(),"surrender");Check(b.Phase==Phase.Lost&&b.EndCause=="전투 포기"&&b.Gold==gold&&b.Kills==kills,"result no bonus");Check(!b.Surrender(),"cannot repeat");b.Step(10);Check(b.Phase==Phase.Lost,"stays ended");var retry=checkpoint.CopyCombat();Check(retry.Phase==Phase.Fighting&&retry.Wave==1&&retry.Gold==checkpoint.Gold,"checkpoint retained");}Console.WriteLine("PASS "+n+" surrender and retry checks");}}
